SELECT p.gender, CAST(p.anchor_age AS INT) AS age, h.admission_type_id, d.icd_code, i.infectious, s.stay_length, COUNT(*) AS num_admissions, AVG(l.value) AS avg_imaging_value, MIN(l.value) AS min_imaging_value, MAX(l.value) AS max_imaging_value FROM patients p JOIN admissions h ON p.subject_id = h.subject_id JOIN diagnoses_icd d ON h.subject_id = d.subject_id JOIN labevents l ON h.subject_id = l.subject_id AND h.hadm_id = l.hadm_id JOIN microbiologyevents m ON h.subject_id = m.subject_id AND h.hadm_id = m.hadm_id JOIN stay s ON h.subject_id = s.subject_id AND h.hadm_id = s.hadm_id JOIN d_items i ON l.itemid = i.itemid WHERE p.gender = 'F' AND CAST(p.anchor_age AS INT) BETWEEN 45 AND 55 AND h.admission_type_id = 2 AND s.stay_length BETWEEN 1 AND 7 AND i.infectious = 'Y' GROUP BY p.gender, age, h.admission_type_id, d.icd_code, i.infectious, s.stay_length ORDER BY num_admissions DESC NULLS LAST;